# import necessary packages
import hashlib
import random
from collections import OrderedDict, namedtuple
from queue import Queue
from typing import List, Dict

# Define necessary namedtuples
Transaction = namedtuple('Transaction', ['sender', 'recipient', 'amount', 'fee', 'timestamp', 'signature'])
Header = namedtuple('Header', ['version', 'index', 'timestamp', 'previous_hash', 'root_hash', 'proof'])
Block = namedtuple('Block', ['header', 'transactions'])

class Blockchain:
    def __init__(self, version: float):
        self.chain: OrderedDict[Header, List[Transaction]] = OrderedDict()
        self.transaction_pool: List[Transaction] = []
        self.version = version
        self.create_genesis_block()

    def create_genesis_block(self):
        genesis_header = Header(0, 0, 768894480, 0, 0, 0)
        self.chain[genesis_header] = []

    def check_balance(self, key: str, timestamp: float) -> int:
        balance = 0
        for block_transactions in self.chain.values():
            for transaction in block_transactions:
                if transaction.sender == key:
                    balance -= transaction.amount + transaction.fee
                if transaction.recipient == key:
                    balance += transaction.amount
        for transaction in self.transaction_pool:
            if transaction.sender == key and transaction.timestamp < timestamp:
                balance -= transaction.amount + transaction.fee
            if transaction.recipient == key and transaction.timestamp < timestamp:
                balance += transaction.amount
        return balance

    @staticmethod
    def hash(data: str) -> str:
        return hashlib.sha256(data.encode()).hexdigest()

# main function
def main_solution(user_key: str, timestamp: float) -> Dict[str, int]:
    blockchain = Blockchain(version=1.0)
    balance = blockchain.check_balance(user_key, timestamp)
    return {"balance": balance}

